/* CLN4U — Unit 4: Crime and Criminal Law — levels 1–4 */
window.QBANK = window.QBANK || [];
window.QBANK.push(
/* ---------- Lesson 1: Foundations of Criminal Law ---------- */
{u:4,l:1,t:"Vocabulary",d:1,q:"What does actus reus mean?",a:"The guilty act — the physical act or conduct that constitutes part of a crime",x:["The guilty mind — the intent behind the act","A killing that is not a crime","A conviction later shown to be wrong"]},
{u:4,l:1,t:"Vocabulary",d:1,q:"What does mens rea mean?",a:"The guilty mind — the mental intent or state of mind behind a criminal act",x:["The guilty act — the physical conduct","A plea that maintains innocence","A witness's retraction"]},
{u:4,l:1,t:"Vocabulary",d:1,q:"What is culpable homicide?",a:"A killing for which the law holds someone criminally responsible, such as murder or manslaughter",x:["A killing that is not a crime, such as justified self-defence","Any accidental death","A death caused by a stranger"]},
{u:4,l:1,t:"Vocabulary",d:1,q:"What is non-culpable homicide?",a:"A killing that is not a crime, such as justified self-defence or accidental death without negligence",x:["Murder in the first degree","A killing with intent","Manslaughter"]},
{u:4,l:1,t:"Vocabulary",d:1,q:"What is tunnel vision in an investigation?",a:"A bias where police or prosecutors focus on one suspect early and interpret all evidence to fit that theory",x:["A technique for examining physical evidence","A rule requiring jurors to focus on one witness","A type of forensic test"]},
{u:4,l:1,t:"Vocabulary",d:1,q:"What is a wrongful conviction?",a:"A conviction of a person who did not commit the offence, later shown by new evidence",x:["A conviction overturned on a technicality","A conviction for a summary offence","A conviction without a jury"]},
{u:4,l:1,t:"Vocabulary",d:1,q:"What is a hybrid offence?",a:"An offence where the Crown chooses whether to proceed summarily or by indictment",x:["An offence tried in two courts at once","An offence against both person and property","A provincial offence"]},
{u:4,l:1,t:"Vocabulary",d:1,q:"What is a strict liability offence?",a:"An offence requiring no mens rea at all — such as most provincial offences like speeding",x:["An offence requiring proof of intent","An offence that always goes to a jury","An international crime"]},
{u:4,l:1,t:"Theories & Concepts",d:1,q:"Which category of offence includes assault, homicide, and sexual offences?",a:"Offences against the person",x:["Offences against property","Offences against public order and morality","Strict liability offences"]},
{u:4,l:1,t:"Theories & Concepts",d:1,q:"Which category of offence includes theft, break and enter, and fraud?",a:"Offences against property",x:["Offences against the person","Offences against public order","Hybrid offences"]},
{u:4,l:1,t:"Theories & Concepts",d:1,q:"Which category of offence includes obstruction of justice and public mischief?",a:"Offences against public order and morality",x:["Offences against the person","Offences against property","Summary offences"]},
{u:4,l:1,t:"Cases & Rulings",d:1,q:"Which 2015 case found Canada's prohibition on assisted suicide violated section 7 of the Charter?",a:"Carter v. Canada",x:["R. v. Oakes","R. v. Latimer","R. v. Jordan"]},
{u:4,l:1,t:"Theories & Concepts",d:2,q:"What must generally be proven together, beyond a reasonable doubt, for a criminal conviction?",a:"Actus reus and mens rea",x:["Motive and opportunity","A confession and a witness","Actus reus and a jury verdict"]},
{u:4,l:1,t:"Theories & Concepts",d:2,q:"Why is there no crime without a prohibited act, no matter what someone thinks?",a:"Because actus reus — the physical act — is a required element of a crime",x:["Because thoughts are always legal","Because mens rea is never required","Because only property crimes count"]},
{u:4,l:1,t:"Theories & Concepts",d:2,q:"What levels of mental state can satisfy mens rea for most serious crimes?",a:"Intent, or at least recklessness or criminal negligence",x:["Only premeditated planning","Only a written confession","Only motive"]},
{u:4,l:1,t:"Theories & Concepts",d:2,q:"Why don't you need to intend to speed to be guilty of speeding?",a:"Speeding is a strict liability offence requiring no mens rea",x:["Speeding is an indictable offence","Speeding requires a jury","Speeding is a federal crime"]},
{u:4,l:1,t:"Theories & Concepts",d:2,q:"How does the definition of 'crime' change over time, according to the course?",a:"It reflects a society's values at a given moment, which differ across countries and change over time",x:["It is fixed by natural law and never changes","It is the same in every country","It is set permanently by the UN"]},
{u:4,l:1,t:"Cases & Rulings",d:2,q:"How does assisted suicide illustrate that crime is not fixed?",a:"It was criminal in Canada until Carter v. Canada (2015) but remains a serious crime in many other countries",x:["It has always been legal everywhere","It was legalized by the Criminal Code in 1892","It is criminal in every country"]},
{u:4,l:1,t:"Theories & Concepts",d:2,q:"Which examples show laws varying by country or even by province?",a:"Legal drinking age, gambling laws, and cannabis regulation",x:["Murder, theft, and fraud","Treason and piracy","Genocide and war crimes"]},
{u:4,l:1,t:"Theories & Concepts",d:2,q:"What determines whether a hybrid offence is tried summarily or by indictment?",a:"The Crown's choice, based on the severity of the specific case",x:["The accused's choice","A coin toss by the judge","The province's rules"]},
{u:4,l:1,t:"Theories & Concepts",d:2,q:"How does Unit 1's presumption of innocence connect to the elements of a crime?",a:"The Crown must prove both actus reus and mens rea beyond a reasonable doubt",x:["The accused must prove they lacked mens rea","The judge presumes mens rea","Innocence applies only to property crimes"]},
{u:4,l:1,t:"Theories & Concepts",d:2,q:"What is the difference between murder and justified self-defence in course terms?",a:"Murder is culpable homicide; justified self-defence is non-culpable homicide",x:["Both are culpable homicide","Both are non-culpable","Murder is a strict liability offence"]},
{u:4,l:1,t:"Theories & Concepts",d:3,q:"A person plans to rob a bank but never does anything. Which element of a crime is missing?",a:"Actus reus",x:["Mens rea","A victim","A jury"]},
{u:4,l:1,t:"Theories & Concepts",d:3,q:"A driver accidentally takes a coat identical to theirs from a restaurant. Which element of theft is missing?",a:"Mens rea — there was no intent to steal",x:["Actus reus — nothing was taken","Both elements are present","The offence is strict liability"]},
{u:4,l:1,t:"Theories & Concepts",d:3,q:"A driver is caught going 20 km/h over the limit and says they didn't notice. Are they guilty?",a:"Yes — speeding is a strict liability offence requiring no mens rea",x:["No — mens rea is required for all offences","No — because they confessed","Only if a jury convicts"]},
{u:4,l:1,t:"Theories & Concepts",d:3,q:"A homeowner kills an armed intruder in justified self-defence. How does the law classify this?",a:"Non-culpable homicide",x:["Culpable homicide","Manslaughter","First-degree murder"]},
{u:4,l:1,t:"Theories & Concepts",d:3,q:"Someone is charged with fraud. Which category of offence is this?",a:"Offences against property",x:["Offences against the person","Offences against public order","Strict liability"]},
{u:4,l:1,t:"Theories & Concepts",d:3,q:"Someone is charged with obstruction of justice. Which category?",a:"Offences against public order and morality",x:["Offences against the person","Offences against property","Non-culpable homicide"]},
{u:4,l:1,t:"Vocabulary",d:3,q:"For a minor assault, the Crown decides to proceed summarily; for a serious one, by indictment. What kind of offence is assault here?",a:"A hybrid offence",x:["A strict liability offence","A summary-only offence","An international crime"]},
{u:4,l:1,t:"Vocabulary",d:3,q:"Detectives decide early that a neighbour is guilty and dismiss every lead pointing elsewhere. Which vocabulary term applies?",a:"Tunnel vision",x:["Mens rea","Recantation","Disclosure"]},
{u:4,l:1,t:"Laws & Documents",d:3,q:"An act is a crime in Canada but legal in another country. According to the course, what does this show?",a:"That what counts as a crime reflects a society's values and varies by place",x:["That one country must be wrong","That international law has standardized crime","That the act is not really a crime anywhere"]},
{u:4,l:1,t:"Laws & Documents",d:4,q:"What matters more in deciding guilt — what someone did or what they intended? What does the course's answer imply?",a:"Both generally matter: the act (actus reus) and the mind (mens rea) must be proven together, except in strict liability offences",x:["Only the act matters","Only the intent matters","Neither — guilt is decided by the jury's feelings"]},
{u:4,l:1,t:"Theories & Concepts",d:4,q:"Should international law try to standardize what counts as a crime across all countries? What is the tension?",a:"Standardizing could protect universal rights, but crime definitions reflect each society's values, raising the relativism questions from Unit 3",x:["There is no tension — all countries already agree","International law has no role in crime","Standardization is impossible for any crime"]},
{u:4,l:1,t:"Laws & Documents",d:4,q:"How does Carter v. Canada connect Unit 4 to Unit 3's Charter lessons?",a:"A criminal prohibition was struck down because it violated section 7 — the Charter reshaping the definition of crime",x:["It invoked the notwithstanding clause","It concerned mobility rights","It was decided by the ICC"]},
{u:4,l:1,t:"Cases & Rulings",d:4,q:"Why does the course introduce 'tunnel vision' and 'wrongful conviction' in Lesson 1, before any case studies?",a:"Because the next lessons show these same patterns recurring across three cases in different decades and countries",x:["Because they are the only crimes studied","Because they are international crimes","Because they are elements of every offence"]},
{u:4,l:1,t:"People & Institutions",d:4,q:"How does the summary/indictable distinction from Unit 2 expand in Unit 4?",a:"Unit 4 adds hybrid offences, where the Crown chooses the route, and classifies offences by type of harm",x:["Unit 4 abolishes the distinction","Unit 4 says all offences are indictable","Unit 4 moves the distinction to civil law"]},
{u:4,l:1,t:"People & Institutions",d:4,q:"Why is it significant that provincial offences are usually strict liability while serious crimes require mens rea?",a:"The more serious the penalty, the more the law demands proof of a guilty mind, reflecting the presumption of innocence",x:["Provincial offences are more serious","Mens rea is easier to prove than actus reus","Strict liability applies only to murder"]},

/* ---------- Lesson 2: From Arrest to Trial ---------- */
{u:4,l:2,t:"Vocabulary",d:1,q:"What is disclosure?",a:"The Crown's legal obligation to share its evidence with the defence before trial",x:["A witness's retraction of testimony","A guilty plea to a lesser charge","A police interrogation technique"]},
{u:4,l:2,t:"Vocabulary",d:1,q:"What is a plea bargain?",a:"An agreement where an accused pleads guilty, often to a lesser charge, in exchange for a reduced sentence or other concession",x:["A plea of not guilty","An appeal to a higher court","A bail condition"]},
{u:4,l:2,t:"Vocabulary",d:1,q:"What is an Alford plea?",a:"A guilty plea in which the accused maintains innocence while acknowledging the Crown likely has enough evidence to convict",x:["A plea of not guilty by reason of insanity","A plea that admits full guilt","A plea entered by the Crown"]},
{u:4,l:2,t:"Vocabulary",d:1,q:"What is recantation?",a:"A witness or informant's later retraction of testimony they previously gave",x:["A judge's final ruling","The Crown's disclosure of evidence","A plea to a lesser charge"]},
{u:4,l:2,t:"Vocabulary",d:1,q:"What does 'disposition' of a charge mean?",a:"How a charge is ultimately resolved: withdrawn, stayed, resolved by guilty plea, or decided at trial",x:["The accused's attitude in court","The sentence after conviction","The police report"]},
{u:4,l:2,t:"Theories & Concepts",d:1,q:"What are the five steps of the legal process from arrest to trial, in order?",a:"Investigation, Arrest & Charge, Bail Hearing, Disclosure & Plea, Trial & Verdict",x:["Trial, Arrest, Investigation, Bail, Verdict","Charge, Trial, Investigation, Plea, Bail","Bail, Investigation, Verdict, Plea, Arrest"]},
{u:4,l:2,t:"Laws & Documents",d:1,q:"Which Charter section requires the accused be informed of the charge and their right to counsel?",a:"Section 10",x:["Section 8","Section 12","Section 7"]},
{u:4,l:2,t:"Theories & Concepts",d:1,q:"Who decides whether an accused is released before trial?",a:"A judge or justice of the peace at a bail hearing",x:["The arresting officer","The Crown prosecutor","A jury"]},
{u:4,l:2,t:"Theories & Concepts",d:1,q:"What standard of proof must the Crown meet at trial?",a:"Beyond a reasonable doubt",x:["Balance of probabilities","Reasonable grounds","Articulable cause"]},
{u:4,l:2,t:"Theories & Concepts",d:1,q:"Which form of evidence does the course call one of the least reliable?",a:"Eyewitness testimony",x:["DNA evidence","Fingerprints","Documentary evidence"]},
{u:4,l:2,t:"Theories & Concepts",d:2,q:"What happens at the Investigation stage?",a:"Police gather witness statements, physical evidence, forensic testing, and (where authorized) surveillance or search warrants",x:["The accused enters a plea","A jury delivers a verdict","The Crown discloses evidence"]},
{u:4,l:2,t:"Theories & Concepts",d:2,q:"What must exist for police to lay a charge?",a:"Reasonable grounds",x:["A confession","A conviction","A jury verdict"]},
{u:4,l:2,t:"Theories & Concepts",d:2,q:"What does a bail hearing balance?",a:"Public safety against the presumption of innocence",x:["The Crown's budget against the defence's","Speed against accuracy","Federal against provincial law"]},
{u:4,l:2,t:"Theories & Concepts",d:2,q:"How do most criminal cases in Canada end?",a:"In a guilty plea rather than a full trial",x:["In acquittal at trial","In a jury verdict","In a mistrial"]},
{u:4,l:2,t:"Theories & Concepts",d:2,q:"Why is forensic evidence a potential weak point despite seeming reliable?",a:"Forensic methods vary enormously in scientific validity, and some techniques used for decades have been discredited",x:["Forensic evidence is never admissible","Juries ignore forensic evidence","Forensic evidence is always falsified"]},
{u:4,l:2,t:"Theories & Concepts",d:2,q:"Why is eyewitness memory unreliable?",a:"Memory is reconstructive, not a recording, and can be distorted by stress, suggestion, and time",x:["Eyewitnesses always lie","Memory is a perfect recording","Eyewitnesses are rarely present"]},
{u:4,l:2,t:"Theories & Concepts",d:2,q:"Who is especially vulnerable to giving false confessions?",a:"Young, vulnerable, or intellectually disabled suspects subjected to lengthy or coercive interrogation",x:["Experienced criminals","Police officers","Lawyers"]},
{u:4,l:2,t:"Theories & Concepts",d:2,q:"Why does disposition matter for wrongful convictions?",a:"If flawed evidence leads to an early guilty plea, the case may never get the scrutiny a full trial would provide",x:["Because pleas are never accepted","Because trials are always wrong","Because disposition means acquittal"]},
{u:4,l:2,t:"Theories & Concepts",d:2,q:"What do trial-level protections like a jury apply to?",a:"Only the small fraction of cases that go to a full trial",x:["Every criminal charge","All plea bargains","All bail hearings"]},
{u:4,l:2,t:"Theories & Concepts",d:2,q:"Why does Lesson 2 say to 'keep the evidence slide in mind' for the next three lessons?",a:"Every wrongful conviction case studied involves at least one of the weak points: forensic error, eyewitness error, or false confession",x:["Because the slide will be on the test only","Because the cases involve no evidence","Because evidence is never wrong"]},
{u:4,l:2,t:"Theories & Concepts",d:2,q:"What options exist for resolving a charge without a full trial?",a:"Plea agreements, diversion programs, or withdrawal",x:["Appeal, retrial, or pardon","Bail, sentencing, or parole","Arrest, charge, or search"]},
{u:4,l:2,t:"Theories & Concepts",d:2,q:"What is the difference between a plea bargain and an Alford plea?",a:"In a plea bargain the accused pleads guilty; in an Alford plea the accused pleads guilty while formally maintaining innocence",x:["They are the same","An Alford plea is a not-guilty plea","A plea bargain requires a jury"]},
{u:4,l:2,t:"Laws & Documents",d:3,q:"Police arrest someone but do not tell them why or that they may call a lawyer. Which stage and Charter right are involved?",a:"Arrest & Charge; section 10",x:["Bail Hearing; section 12","Trial; section 11(f)","Investigation; section 8"]},
{u:4,l:2,t:"Cases & Rulings",d:3,q:"The Crown refuses to show the defence a witness statement before trial. Which obligation is breached?",a:"Disclosure",x:["Recantation","Disposition","Bail"]},
{u:4,l:2,t:"Cases & Rulings",d:3,q:"An innocent person pleads guilty to a lesser charge to avoid a possible life sentence, while still insisting they did nothing. What is this?",a:"An Alford plea",x:["A recantation","A stay of proceedings","A diversion"]},
{u:4,l:2,t:"Vocabulary",d:3,q:"A jailhouse informant admits years later that his testimony was false. What is this called?",a:"Recantation",x:["Disclosure","Plea bargain","Disposition"]},
{u:4,l:2,t:"Cases & Rulings",d:3,q:"A judge must decide whether to release an accused before trial. What stage is this?",a:"Bail Hearing",x:["Disclosure & Plea","Trial & Verdict","Investigation"]},
{u:4,l:2,t:"Cases & Rulings",d:3,q:"A 15-year-old confesses after 10 hours of questioning with no parent present. Which evidence weak point is this?",a:"False or coerced confession",x:["Eyewitness misidentification","Flawed forensic science","Jailhouse informant"]},
{u:4,l:2,t:"Cases & Rulings",d:3,q:"A conviction rests on a bite-mark analysis technique later discredited. Which weak point is this?",a:"Flawed forensic science",x:["Coerced confession","Eyewitness misidentification","Disclosure failure"]},
{u:4,l:2,t:"Theories & Concepts",d:3,q:"A stressed witness picks a suspect from a lineup months after a brief encounter. Which weak point?",a:"Eyewitness misidentification",x:["False confession","Jailhouse informant","Tunnel vision"]},
{u:4,l:2,t:"Cases & Rulings",d:3,q:"Why might an innocent person plead guilty to a lesser charge?",a:"To avoid the risk of a much harsher sentence if convicted at trial on flawed but convincing evidence",x:["Because pleading guilty is always required","Because innocent people cannot go to trial","Because the Crown pays them"]},
{u:4,l:2,t:"Cases & Rulings",d:4,q:"Why does Canada require separate steps (bail, disclosure, plea) between charge and trial?",a:"Each step protects the accused's rights and allows the case to be tested before trial-level resources are used",x:["To delay justice","Because trials are illegal without them","To increase the number of convictions"]},
{u:4,l:2,t:"Cases & Rulings",d:4,q:"Where in the process is a wrongful conviction most likely to start going wrong, based on the three case studies?",a:"At the evidence-gathering stage — coerced confessions, pressured witnesses, and flawed forensics",x:["At sentencing","At the appeal","At Royal Assent"]},
{u:4,l:2,t:"Cases & Rulings",d:4,q:"Why are confessions so dangerous when juries give them 'enormous weight'?",a:"Jurors assume no one would confess falsely, so a coerced confession can outweigh the absence of physical evidence",x:["Because confessions are always true","Because judges reject confessions","Because confessions are inadmissible"]},
{u:4,l:2,t:"Cases & Rulings",d:4,q:"How does the fact that most cases end in guilty pleas affect the protective value of jury trials?",a:"Jury protections apply only to the small fraction of cases that reach trial, so flawed evidence can produce convictions without that scrutiny",x:["Juries review every guilty plea","Guilty pleas are always accurate","Jury trials are the norm"]},
{u:4,l:2,t:"People & Institutions",d:4,q:"How does the disclosure rule connect to the Unit 1 principle of fairness?",a:"Fairness means an accused should know the Crown's evidence to prepare a defence — disclosure is that principle in practice",x:["Disclosure is about impartiality only","Disclosure violates fairness","Fairness requires no disclosure"]},
{u:4,l:2,t:"Cases & Rulings",d:4,q:"Why does the course treat physical evidence, eyewitnesses, and confessions as a single theme?",a:"Each feels compelling to a jury yet has documented failure modes that recur in wrongful convictions",x:["Because they are all equally reliable","Because they are never used at trial","Because only one is ever presented"]},

/* ---------- Lesson 3: Central Park Five ---------- */
{u:4,l:3,t:"Cases & Rulings",d:1,q:"On what date did the Central Park Jogger attack occur?",a:"April 19, 1989",x:["May 5, 1993","January 31, 1969","December 19, 2002"]},
{u:4,l:3,t:"Cases & Rulings",d:1,q:"Who was the victim in the Central Park Jogger case?",a:"Trisha Meili",x:["Gail Miller","Vicki Hutcheson","Nichol John"]},
{u:4,l:3,t:"People & Institutions",d:1,q:"Which of these was one of the Central Park Five?",a:"Korey Wise",x:["Damien Echols","Jason Baldwin","Larry Fisher"]},
{u:4,l:3,t:"People & Institutions",d:1,q:"Who confessed in 2002 to being the sole attacker of Trisha Meili?",a:"Matias Reyes",x:["Korey Wise","Larry Fisher","Michael Carson"]},
{u:4,l:3,t:"Modern Connections",d:1,q:"Who directed the 2012 documentary The Central Park Five?",a:"Ken Burns, Sarah Burns, and David McMahon",x:["Joe Berlinger and Bruce Sinofsky","Peter Jackson","Charles Officer"]},
{u:4,l:3,t:"Cases & Rulings",d:1,q:"How old were the Central Park Five at the time of their arrest?",a:"14 to 16",x:["18 to 21","10 to 12","25 to 30"]},
{u:4,l:3,t:"Cases & Rulings",d:1,q:"How much did New York City pay to settle the Exonerated Five's lawsuit in 2014?",a:"$41 million",x:["$10 million","$1 million","$410 million"]},
{u:4,l:3,t:"People & Institutions",d:1,q:"Which organizations' case reviews provide the list of common wrongful conviction factors?",a:"The Innocence Project and Innocence Canada",x:["The ICC and ICJ","Human Rights Watch and the ACLU","The SIU and the RCMP"]},
{u:4,l:3,t:"Cases & Rulings",d:1,q:"What term did media use to brand the teenagers' behaviour in Central Park?",a:"'Wilding' by a 'wolf pack'",x:["Satanic panic","Carding","Rioting"]},
{u:4,l:3,t:"Cases & Rulings",d:1,q:"By what name are the five men now known?",a:"The Exonerated Five",x:["The West Memphis Three","The Famous Five","The Innocence Five"]},
{u:4,l:3,t:"Theories & Concepts",d:2,q:"What are the five most common factors in wrongful convictions?",a:"Eyewitness misidentification, false or coerced confessions, tunnel vision, flawed forensic science, and jailhouse informant testimony",x:["Bail, disclosure, plea, trial, and sentencing","Motive, means, opportunity, alibi, and confession","Race, age, wealth, education, and location"]},
{u:4,l:3,t:"Theories & Concepts",d:2,q:"Why are wrongful convictions 'rarely caused by one single failure'?",a:"They usually involve several compounding factors, each reinforcing the others",x:["Because one factor is never enough to convict","Because courts catch single errors","Because juries require multiple witnesses"]},
{u:4,l:3,t:"Cases & Rulings",d:2,q:"Under what conditions did the five teenagers confess?",a:"After hours of aggressive interrogation, mostly without parents or lawyers present",x:["With their lawyers present and after full disclosure","On video, voluntarily, at the scene","After DNA evidence was shown to them"]},
{u:4,l:3,t:"Cases & Rulings",d:2,q:"What physical evidence connected the five to the attack?",a:"None — and their statements had significant inconsistencies",x:["DNA from all five","Fingerprints from two of them","A weapon found on one"]},
{u:4,l:3,t:"Cases & Rulings",d:2,q:"How long were the sentences served by the five?",a:"6 to 13 years",x:["1 to 2 years","20 to 30 years","Life without parole"]},
{u:4,l:3,t:"Cases & Rulings",d:2,q:"How did Matias Reyes come to confess?",a:"He encountered Korey Wise in prison and confessed, providing accurate details not made public",x:["Police found his DNA in 1989","He wrote a letter to the newspaper","He was offered a plea deal"]},
{u:4,l:3,t:"Cases & Rulings",d:2,q:"What did DNA testing show in 2002?",a:"It matched Reyes to crime-scene evidence that had never matched any of the five",x:["It matched all five teenagers","It was inconclusive","It matched Korey Wise only"]},
{u:4,l:3,t:"Cases & Rulings",d:2,q:"What happened on December 19, 2002?",a:"A New York State Supreme Court justice vacated all five convictions",x:["The five were arrested","Reyes was executed","The documentary premiered"]},
{u:4,l:3,t:"Theories & Concepts",d:2,q:"How did tunnel vision operate in the Central Park case?",a:"Once investigators settled on the five, evidence like inconsistencies between confessions was interpreted to fit that theory rather than questioned",x:["Investigators considered every suspect equally","Investigators ignored the confessions","Investigators relied only on DNA"]},
{u:4,l:3,t:"Theories & Concepts",d:2,q:"What role did media coverage play?",a:"It intensified public pressure for swift convictions",x:["It exposed the wrongful conviction immediately","It had no effect","It led to Reyes's arrest in 1989"]},
{u:4,l:3,t:"Modern Connections",d:2,q:"Why is the Central Park Five case still widely cited?",a:"It is one of the most cited examples of coerced juvenile confessions and informs debates about interrogating minors",x:["It was the first use of DNA evidence","It abolished plea bargains","It created the Innocence Project"]},
{u:4,l:3,t:"Theories & Concepts",d:2,q:"Why does the course say the recurrence of factors across three cases is 'not a coincidence'?",a:"The same systemic weaknesses in evidence-gathering produce wrongful convictions across decades and countries",x:["Because the cases involved the same police","Because the cases were in the same city","Because coincidence is impossible"]},
{u:4,l:3,t:"Cases & Rulings",d:3,q:"Police obtain confessions from several teens that contradict each other on key facts, and no physical evidence links them. Which two wrongful conviction factors are present?",a:"Coerced confessions and tunnel vision",x:["Eyewitness misidentification and forensic error","Jailhouse informant and recantation","Disclosure failure and bail denial"]},
{u:4,l:3,t:"Laws & Documents",d:3,q:"A 14-year-old is interrogated without a parent or lawyer. Which Charter protections from Unit 3 would be relevant in Canada?",a:"Section 10 (right to counsel) and legal rights in sections 7–14",x:["Section 6 (mobility) and section 23","Section 3 (voting) and section 33","Section 16 (language) and section 15"]},
{u:4,l:3,t:"Modern Connections",d:3,q:"Intense news coverage labels suspects guilty before trial. Which Unit 1 principles of justice are at risk?",a:"Impartiality and innocence until proven guilty",x:["Equality and equity","Rule of law and habeas corpus","Fairness and currency"]},
{u:4,l:3,t:"Cases & Rulings",d:3,q:"A man already serving life confesses to a crime others were convicted of, and DNA confirms it. Which case is this?",a:"The Central Park Five (Matias Reyes)",x:["West Memphis Three","David Milgaard","R. v. Brown"]},
{u:4,l:3,t:"Cases & Rulings",d:3,q:"A jury convicts based on confessions alone despite no physical evidence. Which Lesson 2 insight explains this?",a:"Juries give confessions enormous weight despite documented false confessions",x:["Juries never trust confessions","Juries require DNA to convict","Confessions are inadmissible"]},
{u:4,l:3,t:"Cases & Rulings",d:3,q:"At what point does the course suggest an investigator 'could have changed course'?",a:"When inconsistencies between confessions and the lack of physical evidence emerged",x:["Only after the 2002 DNA test","At sentencing","Never — the evidence was conclusive"]},
{u:4,l:3,t:"Cases & Rulings",d:3,q:"Which Lesson 2 evidence weak point is the centrepiece of the Central Park Five case?",a:"False or coerced confessions",x:["Flawed forensic science","Eyewitness misidentification","Jailhouse informant"]},
{u:4,l:3,t:"Cases & Rulings",d:4,q:"Why might a false confession from a 14-year-old be more damaging to a case than one from an adult?",a:"Juveniles are more vulnerable to coercion, less able to assert rights to counsel, yet juries treat their confessions as equally convincing",x:["Juvenile confessions are automatically excluded","Adults never confess falsely","Juvenile confessions carry lighter sentences"]},
{u:4,l:3,t:"Cases & Rulings",d:4,q:"How did race and public fear interact with tunnel vision in this case?",a:"Media framing of Black and Latino teens as a 'wolf pack' amplified pressure for quick convictions, reinforcing investigators' fixed theory",x:["Race played no role","Public fear slowed the investigation","Tunnel vision reduced media interest"]},
{u:4,l:3,t:"Cases & Rulings",d:4,q:"Why did it take a chance encounter in prison, rather than the justice system itself, to correct the Central Park case?",a:"Once convictions were secured, the system had no mechanism actively re-examining them; new evidence surfaced only by chance",x:["Because the system reviewed every case annually","Because DNA testing was illegal","Because the five had already been pardoned"]},
{u:4,l:3,t:"Cases & Rulings",d:4,q:"How does the Central Park Five case connect Unit 2's Lesson 1 (racial profiling) to Unit 4?",a:"Both show race being treated as a proxy for criminality, in policing and in prosecution",x:["Both involved the Toronto Raptors","Both were Canadian cases","Both involved the notwithstanding clause"]},
{u:4,l:3,t:"Cases & Rulings",d:4,q:"What does the $41 million settlement illustrate about remedies for wrongful conviction?",a:"Civil compensation can follow exoneration, but it cannot restore the years lost",x:["Compensation proves the five were guilty","Settlements replace the need for exoneration","Compensation is automatic in all cases"]},

/* ---------- Lesson 4: West Memphis Three ---------- */
{u:4,l:4,t:"Cases & Rulings",d:1,q:"Where and when did the Robin Hood Hills murders occur?",a:"West Memphis, Arkansas, May 5–6, 1993",x:["New York City, April 1989","Saskatoon, January 1969","Nuremberg, 1945"]},
{u:4,l:4,t:"People & Institutions",d:1,q:"Who were the West Memphis Three?",a:"Damien Echols, Jason Baldwin, and Jessie Misskelley Jr.",x:["Korey Wise, Yusef Salaam, and Raymond Santana","David Milgaard, Ron Wilson, and Nichol John","Steve Branch, Christopher Byers, and Michael Moore"]},
{u:4,l:4,t:"People & Institutions",d:1,q:"Who were the three victims in the West Memphis case?",a:"Steve Branch, Christopher Byers, and Michael Moore",x:["Trisha Meili and two others","Gail Miller and two others","Damien Echols and two friends"]},
{u:4,l:4,t:"Vocabulary",d:1,q:"What was the 'Satanic Panic'?",a:"A period of widespread, largely unfounded fear in the U.S. that hidden satanic cults were abusing and murdering children",x:["A heavy metal music festival","A police training program","A Supreme Court ruling"]},
{u:4,l:4,t:"People & Institutions",d:1,q:"Which juvenile probation officer gave police Damien Echols's name?",a:"Jerry Driver",x:["Gary Gitchell","John Fogleman","Frank Peretti"]},
{u:4,l:4,t:"People & Institutions",d:1,q:"Who led the interrogation of Jessie Misskelley?",a:"Gary Gitchell",x:["Jerry Driver","John Fogleman","Michael Carson"]},
{u:4,l:4,t:"People & Institutions",d:1,q:"Who was the prosecutor in the West Memphis Three trials?",a:"John Fogleman",x:["Gary Gitchell","Frank Peretti","Edward MacCallum"]},
{u:4,l:4,t:"People & Institutions",d:1,q:"Which inmate falsely claimed Jason Baldwin confessed to him?",a:"Michael Carson",x:["Matias Reyes","Albert Cadrain","Larry Fisher"]},
{u:4,l:4,t:"Modern Connections",d:1,q:"Which filmmakers made the Paradise Lost trilogy?",a:"Joe Berlinger and Bruce Sinofsky",x:["Ken Burns and Sarah Burns","Peter Jackson","Charles Officer"]},
{u:4,l:4,t:"Modern Connections",d:1,q:"Which director produced West of Memphis (2012)?",a:"Peter Jackson",x:["Ken Burns","Joe Berlinger","Roger Ebert"]},
{u:4,l:4,t:"Modern Connections",d:1,q:"Which 2014 dramatized film about the case starred Colin Firth and Reese Witherspoon?",a:"Devil's Knot",x:["West of Memphis","Paradise Lost","The Mauritanian"]},
{u:4,l:4,t:"Cases & Rulings",d:1,q:"What sentence did Damien Echols receive?",a:"Death",x:["Life without parole","Life plus two 20-year terms","20 years"]},
{u:4,l:4,t:"Cases & Rulings",d:1,q:"On what date were the West Memphis Three released?",a:"August 19, 2011",x:["December 19, 2002","April 1992","May 5, 1993"]},
{u:4,l:4,t:"Cases & Rulings",d:1,q:"Which U.S. case gives the Alford plea its name?",a:"North Carolina v. Alford",x:["Marbury v. Madison","Trump v. CASA","Miranda v. Arizona"]},
{u:4,l:4,t:"People & Institutions",d:1,q:"Which musician from Pearl Jam advocated for the West Memphis Three?",a:"Eddie Vedder",x:["Henry Rollins","Johnny Depp","Colin Firth"]},
{u:4,l:4,t:"Cases & Rulings",d:2,q:"Why did investigators first focus on Damien Echols?",a:"He wore black, listened to heavy metal, and was interested in Wicca and the occult — not physical evidence",x:["His DNA was found at the scene","He confessed immediately","A witness saw him with the victims"]},
{u:4,l:4,t:"Cases & Rulings",d:2,q:"What were the conditions of Misskelley's interrogation?",a:"About 12 hours, with an IQ around 72, no parent or lawyer for most of it, and only a few minutes recorded",x:["One hour, fully recorded, with a lawyer","Two days with his parents present","A brief recorded statement at home"]},
{u:4,l:4,t:"Cases & Rulings",d:2,q:"What did Gary Gitchell answer when asked his confidence on a scale of 1 to 10?",a:"'11'",x:["'5'","'10'","'I'm not sure'"]},
{u:4,l:4,t:"Cases & Rulings",d:2,q:"What were the three elements that 'closed the case' at trial?",a:"The Hutcheson testimony plus Misskelley's confession, the knife from the lake, and Michael Carson's jailhouse testimony",x:["DNA, fingerprints, and video","A confession, an eyewitness, and a weapon with prints","Three independent eyewitnesses"]},
{u:4,l:4,t:"Cases & Rulings",d:2,q:"Why was the knife evidence later called 'outlandish'?",a:"Dozens of independent forensic professionals rejected the claim that its serrated edge matched the wounds, and the crime lab had a conflict of interest",x:["The knife was never found","The knife belonged to a police officer","The knife had Echols's fingerprints"]},
{u:4,l:4,t:"Cases & Rulings",d:2,q:"What did Michael Carson later admit?",a:"His testimony was a lie, made while he was high on drugs as a teenager",x:["He was the real killer","He never met Baldwin","He was paid by the defence"]},
{u:4,l:4,t:"Cases & Rulings",d:2,q:"Why was it problematic that Misskelley's confession was used against Echols and Baldwin?",a:"Misskelley did not testify at their trial, so he could not be cross-examined by their defence",x:["Misskelley recanted at their trial","The confession was fully recorded","Echols and Baldwin had confessed too"]},
{u:4,l:4,t:"Cases & Rulings",d:2,q:"What did the 2007 DNA testing show?",a:"None of the genetic material recovered could be attributed to Echols, Baldwin, or Misskelley",x:["It matched all three","It matched Misskelley only","It was never completed"]},
{u:4,l:4,t:"Cases & Rulings",d:2,q:"Why did Jason Baldwin initially refuse the Alford plea?",a:"He refused any plea requiring an admission of guilt, agreeing only when Echols's execution date made it life-or-death",x:["He wanted a larger settlement","He preferred to stay in prison","His lawyer advised against release"]},
{u:4,l:4,t:"Cases & Rulings",d:2,q:"What was the legal consequence of the Alford plea for the three?",a:"They were legally guilty while publicly maintaining innocence — released but not fully exonerated",x:["They were fully exonerated","They were pardoned by the governor","They received $41 million"]},
{u:4,l:4,t:"Cases & Rulings",d:2,q:"Why do the Robin Hood Hills murders remain officially unsolved?",a:"The case was closed through a plea rather than a new trial or exoneration, so no one else has been charged",x:["The evidence was destroyed","The victims were never identified","A jury acquitted everyone"]},
{u:4,l:4,t:"Modern Connections",d:2,q:"How did the Paradise Lost filmmakers' view change?",a:"They started with no advocacy intent but gradually became convinced the three were wrongfully convicted",x:["They always believed the three were guilty","They were hired by the defence","They never formed an opinion"]},
{u:4,l:4,t:"Modern Connections",d:2,q:"What is celebrity advocacy credited with in this case?",a:"Keeping the case alive long enough for new forensic testing to eventually take place",x:["Winning the original trial","Discovering the knife","Writing the Alford plea"]},
{u:4,l:4,t:"Cases & Rulings",d:2,q:"What did Vicki Hutcheson tell police?",a:"That occult rituals occurred around her house and she could arrange to 'implicate' Damien Echols",x:["That she saw the murders","That Misskelley was innocent","That the knife was hers"]},
{u:4,l:4,t:"Theories & Concepts",d:3,q:"A suspect is chosen because of his clothing, music, and beliefs rather than evidence. Which two factors from the framework apply?",a:"Moral panic and tunnel vision",x:["Eyewitness error and forensic fraud","Recantation and disclosure","Bail denial and plea bargaining"]},
{u:4,l:4,t:"Cases & Rulings",d:3,q:"A suspect with an intellectual disability is questioned for 12 hours, mostly unrecorded. Which evidence weak point does this create?",a:"A coerced, unreliable confession",x:["Eyewitness misidentification","Flawed forensic science","Jailhouse informant testimony"]},
{u:4,l:4,t:"Theories & Concepts",d:3,q:"An expert says a knife 'matches' wounds, but dozens of independent experts disagree and the lab has ties to the prosecution. Which factor is this?",a:"Flawed or misrepresented forensic science",x:["Coerced confession","Tunnel vision","Moral panic"]},
{u:4,l:4,t:"Theories & Concepts",d:3,q:"A fellow inmate claims the accused confessed to him, then later admits he lied. Which factor and which Lesson 2 term apply?",a:"Jailhouse informant testimony and recantation",x:["Eyewitness misidentification and disclosure","Forensic error and plea bargain","Tunnel vision and bail"]},
{u:4,l:4,t:"People & Institutions",d:3,q:"A co-accused's statement is used against two defendants who cannot cross-examine him. Which Unit 2 vocabulary and Unit 1 principle are engaged?",a:"Cross-examination and fairness",x:["Disclosure and equality","Testify and impartiality","Counsel and rule of law"]},
{u:4,l:4,t:"Vocabulary",d:3,q:"Defendants plead guilty to secure release while maintaining innocence, because one faces execution. What kind of plea is this?",a:"An Alford plea",x:["A plea bargain admitting guilt","A not-guilty plea","A stay of proceedings"]},
{u:4,l:4,t:"Theories & Concepts",d:3,q:"A community panics over rumours of satanic cults with no evidence. Which Lesson 4 concept describes this?",a:"Moral panic",x:["Tunnel vision","Complementarity","Strain theory"]},
{u:4,l:4,t:"Cases & Rulings",d:3,q:"How many of the three decisive trial elements were physical evidence directly tying the defendants to the scene?",a:"None",x:["One — the knife","Two — the knife and the confession","All three"]},
{u:4,l:4,t:"Cases & Rulings",d:4,q:"How many separate wrongful-conviction factors can be identified in the West Memphis Three case?",a:"At least four: moral panic/tunnel vision, coerced confession, flawed forensics, and jailhouse informant testimony",x:["Only one — the confession","Only two — forensics and DNA","None — the evidence was sound"]},
{u:4,l:4,t:"Cases & Rulings",d:4,q:"Why did it take celebrity involvement and multiple documentaries to get the case reconsidered?",a:"Most wrongful conviction cases never receive sustained attention; without public pressure, the system had little incentive to re-examine a closed case",x:["Because celebrities have legal authority","Because documentaries are admissible evidence","Because the courts asked for publicity"]},
{u:4,l:4,t:"Cases & Rulings",d:4,q:"What would you weigh in advising the three on accepting an Alford plea versus pursuing a new trial?",a:"Immediate release and avoiding execution versus the loss of full exoneration and the chance to identify the real killer",x:["Nothing — a new trial was guaranteed to succeed","Only the cost of lawyers","Whether to appear in a documentary"]},
{u:4,l:4,t:"Cases & Rulings",d:4,q:"How much credit should a recanting witness like Michael Carson receive? What complicates it?",a:"His recantation undermines the conviction, but his admitted drug use and youth raise questions about both his original and later statements",x:["Full credit — recantations are always true","No credit — recantations are never allowed","It is irrelevant to the case"]},
{u:4,l:4,t:"People & Institutions",d:4,q:"How does Roger Ebert's description of Paradise Lost connect to Unit 1's principle of impartiality?",a:"A community willing to 'see Satanism in anyone who looked different' shows prejudice replacing objective judgment",x:["It shows the jury was perfectly impartial","It concerns the rule of law only","It is about equity vs. equality"]},
{u:4,l:4,t:"Cases & Rulings",d:4,q:"Why does the course call the West Memphis case 'built first, evidence sought second'?",a:"Investigators chose suspects from rumour and a probation officer's list, then looked for evidence to support the theory",x:["Because the evidence was collected before the crime","Because the case was never built","Because the DNA came first"]},
{u:4,l:4,t:"Cases & Rulings",d:4,q:"Compare the Central Park Five and West Memphis Three on how the cases ended.",a:"The Central Park Five were fully exonerated after a confession and DNA match; the West Memphis Three were released via Alford plea without exoneration",x:["Both were fully exonerated","Both remain in prison","Both received $41 million"]},

/* ---------- Lesson 5: David Milgaard ---------- */
{u:4,l:5,t:"Cases & Rulings",d:1,q:"Who was the victim in the Milgaard case?",a:"Gail Miller",x:["Trisha Meili","Joyce Milgaard","Nichol John"]},
{u:4,l:5,t:"Cases & Rulings",d:1,q:"In what city was Gail Miller murdered?",a:"Saskatoon",x:["Regina","Calgary","Winnipeg"]},
{u:4,l:5,t:"Cases & Rulings",d:1,q:"On what date was Gail Miller murdered?",a:"January 31, 1969",x:["April 19, 1989","May 5, 1993","September 9, 2004"]},
{u:4,l:5,t:"People & Institutions",d:1,q:"Who actually committed the murder of Gail Miller?",a:"Larry Fisher",x:["Albert Cadrain","Ron Wilson","Matias Reyes"]},
{u:4,l:5,t:"People & Institutions",d:1,q:"Who was David Milgaard's mother and tireless advocate?",a:"Joyce Milgaard",x:["Gail Miller","Nichol John","Vicki Hutcheson"]},
{u:4,l:5,t:"People & Institutions",d:1,q:"Which justice led the Commission of Inquiry into the Milgaard case?",a:"Edward MacCallum",x:["James Boasberg","Claire L'Heureux-Dubé","Philippe Kirsch"]},
{u:4,l:5,t:"Laws & Documents",d:1,q:"What law created Canada's independent Miscarriage of Justice Review Commission?",a:"The David and Joyce Milgaard's Law",x:["The Crimes Against Humanity and War Crimes Act","The Youth Criminal Justice Act","The Cannabis Act"]},
{u:4,l:5,t:"Cases & Rulings",d:1,q:"How many years did Milgaard spend in prison?",a:"Nearly 23",x:["13","18","27"]},
{u:4,l:5,t:"Cases & Rulings",d:1,q:"How much compensation did Milgaard receive from Saskatchewan?",a:"$10 million",x:["$41 million","$1 million","$33,000"]},
{u:4,l:5,t:"People & Institutions",d:1,q:"Who were Milgaard's travelling companions on the 1969 road trip?",a:"Ron Wilson and Nichol John",x:["Larry Fisher and Albert Cadrain","Jim McCloskey and Paul Henderson","Korey Wise and Yusef Salaam"]},
{u:4,l:5,t:"People & Institutions",d:1,q:"Which private investigator and which Centurion Ministries figure assembled evidence pointing to Fisher in 1991?",a:"Paul Henderson and Jim McCloskey",x:["Jerry Driver and Gary Gitchell","Ken Burns and Sarah Burns","Ron Wilson and Nichol John"]},
{u:4,l:5,t:"Cases & Rulings",d:1,q:"In what year did DNA testing clear Milgaard and implicate Fisher?",a:"1997",x:["1992","2004","1991"]},
{u:4,l:5,t:"Cases & Rulings",d:2,q:"How was the evidence against Milgaard obtained?",a:"Police pressured his teenage companions into statements implicating him, through interviews and polygraphs with no adults present",x:["DNA matched Milgaard at the scene","Milgaard confessed on video","An eyewitness saw the attack"]},
{u:4,l:5,t:"Cases & Rulings",d:2,q:"How old was Milgaard when convicted, and what was the sentence?",a:"17, sentenced to life in prison",x:["16, sentenced to 10 years","21, sentenced to death","19, sentenced to 23 years"]},
{u:4,l:5,t:"Cases & Rulings",d:2,q:"Who was Albert Cadrain?",a:"An acquaintance of Milgaard's who rented to Larry Fisher and was also a paid police informant who implicated Milgaard",x:["The lead investigator","Milgaard's defence lawyer","The judge at trial"]},
{u:4,l:5,t:"Cases & Rulings",d:2,q:"What did a 1970 police investigation reveal about Larry Fisher?",a:"He had committed several sexual assaults in the same Saskatoon neighbourhood, but was never seriously pursued for Miller's murder",x:["He had an alibi for the murder","He had moved to Calgary","He was Milgaard's cousin"]},
{u:4,l:5,t:"Cases & Rulings",d:2,q:"What happened to the 1980 tip pointing to Fisher?",a:"It was never followed up",x:["It led to Fisher's arrest","It was disclosed to Milgaard's lawyers","It was investigated and dismissed"]},
{u:4,l:5,t:"Cases & Rulings",d:2,q:"What did Henderson and McCloskey find in 1991?",a:"Striking similarities between Fisher's assaults and Miller's murder, and that authorities had not disclosed Fisher's convictions",x:["A confession from Fisher","DNA evidence","A new eyewitness"]},
{u:4,l:5,t:"Cases & Rulings",d:2,q:"What did the Supreme Court of Canada do in 1992?",a:"Heard the fresh evidence and recommended a new trial, while controversially finding the original trial fair",x:["Declared Milgaard factually innocent","Convicted Larry Fisher","Refused to hear the case"]},
{u:4,l:5,t:"Cases & Rulings",d:2,q:"Why was Milgaard released in April 1992 but not yet exonerated?",a:"Saskatchewan chose not to prosecute him again rather than hold a new trial",x:["He was pardoned by the Governor General","DNA had already cleared him","He escaped from prison"]},
{u:4,l:5,t:"Cases & Rulings",d:2,q:"What happened to Larry Fisher?",a:"Arrested in July 1997, convicted of Miller's murder in November 1999, and died in prison in 2015",x:["He was never charged","He was acquitted in 1999","He confessed in 1969"]},
{u:4,l:5,t:"Cases & Rulings",d:2,q:"On what date did Saskatchewan formally acknowledge Milgaard was 'factually innocent'?",a:"September 9, 2004",x:["April 1992","July 1997","January 31, 1969"]},
{u:4,l:5,t:"Laws & Documents",d:2,q:"Before the Milgaard reform, who controlled wrongful conviction reviews in Canada?",a:"The Minister of Justice, at their discretion",x:["The Supreme Court automatically","An independent commission","Provincial police"]},
{u:4,l:5,t:"Laws & Documents",d:2,q:"What did the David and Joyce Milgaard's Law change?",a:"It took wrongful conviction review out of the Minister's hands and gave it to an independent Miscarriage of Justice Review Commission",x:["It abolished life sentences","It required DNA testing in all trials","It created the Supreme Court"]},
{u:4,l:5,t:"Cases & Rulings",d:2,q:"What happened to Milgaard's first application to the Minister of Justice in 1991?",a:"It was dismissed in February 1991; a second application focusing on Fisher followed six months later",x:["It was accepted immediately","It was referred to the ICC","It was never filed"]},
{u:4,l:5,t:"Cases & Rulings",d:2,q:"How many suspects did Saskatoon police investigate in the Miller case?",a:"More than 160",x:["Three","About 20","Only Milgaard"]},
{u:4,l:5,t:"Cases & Rulings",d:3,q:"Police receive a credible tip pointing to another suspect but never follow it up because they already have a conviction. Which concept applies?",a:"Tunnel vision",x:["Recantation","Complementarity","Strict liability"]},
{u:4,l:5,t:"Cases & Rulings",d:3,q:"Authorities fail to tell the defence that another man with similar convictions lived nearby. Which Lesson 2 obligation was breached?",a:"Disclosure",x:["Bail","Plea bargaining","Cross-examination"]},
{u:4,l:5,t:"Cases & Rulings",d:3,q:"A conviction rests on statements from teenagers pressured by police with no adults present. Which evidence weak point is this?",a:"Pressured or coerced witness statements",x:["Flawed forensic science","Jailhouse informant","Eyewitness misidentification by a stranger"]},
{u:4,l:5,t:"Cases & Rulings",d:3,q:"A paid police informant provides information implicating a suspect. Why should this be treated with caution, based on the framework?",a:"Informant testimony is a recognized wrongful conviction factor, as with Cadrain and Carson",x:["Informants are always reliable","Informants cannot testify","Informants must be police officers"]},
{u:4,l:5,t:"Modern Connections",d:3,q:"A convicted person in Canada today has new evidence of innocence. Where do they now turn, thanks to Milgaard's case?",a:"The independent Miscarriage of Justice Review Commission",x:["The Minister of Justice alone","The ICC","The SIU"]},
{u:4,l:5,t:"Cases & Rulings",d:3,q:"Which Milgaard fact best illustrates that law 'evolves in response to real failures' (Unit 1 theme)?",a:"The case led directly to a new law creating an independent review commission",x:["Milgaard was released in 1992","Fisher died in prison","DNA testing was done in 1997"]},
{u:4,l:5,t:"Cases & Rulings",d:3,q:"Which two wrongful conviction factors appear in all three cases studied (Central Park Five, West Memphis Three, Milgaard)?",a:"Tunnel vision and coerced or pressured statements from young people",x:["Flawed forensics and jailhouse informants","Eyewitness misidentification and bail denial","Moral panic and celebrity advocacy"]},
{u:4,l:5,t:"Cases & Rulings",d:3,q:"A government apologizes and pays compensation but a court has not formally declared innocence. Which stage of the Milgaard story matches this?",a:"1997 — the apology after DNA, before the 2004 'factually innocent' declaration",x:["1970 — the conviction","1992 — the Supreme Court hearing","2022 — Milgaard's death"]},
{u:4,l:5,t:"Cases & Rulings",d:4,q:"Why did the Milgaard case produce a permanent structural change when the American cases did not?",a:"A formal Commission of Inquiry identified systemic failures, and a politically accountable review process was replaced by an independent body",x:["Because American cases involve no systemic failures","Because Canada has no Minister of Justice","Because the American cases were less publicized"]},
{u:4,l:5,t:"People & Institutions",d:4,q:"Is an independent review commission a better model than a process controlled by an elected Minister? What are the trade-offs?",a:"Independence reduces political pressure and conflicts of interest, but removes direct democratic accountability",x:["The Minister model is always better","There are no trade-offs","Commissions can only review federal cases"]},
{u:4,l:5,t:"Cases & Rulings",d:4,q:"Why was the Supreme Court's 1992 finding that the trial was 'fair' controversial?",a:"It recommended a new trial on fresh evidence yet found no police wrongdoing, despite the undisclosed Fisher evidence and pressured witnesses",x:["Because the Court convicted Fisher","Because the Court refused to hear the case","Because Milgaard had confessed"]},
{u:4,l:5,t:"Cases & Rulings",d:4,q:"Why does the course say it matters to study a Canadian wrongful conviction alongside the American ones?",a:"It shows the same patterns occur in Canada's system, not just abroad, and shows how a Canadian case changed Canadian law",x:["Because Canadian cases are always worse","Because American cases are irrelevant","Because Canada has never had a wrongful conviction"]},
{u:4,l:5,t:"Cases & Rulings",d:4,q:"How does the Milgaard case connect disclosure (Lesson 2) to the Unit 1 principle of fairness?",a:"Withholding Fisher's convictions from the defence denied Milgaard the knowledge needed to mount a defence",x:["It shows disclosure is optional","It concerns impartiality only","It involves the Oakes test"]},
{u:4,l:5,t:"Cases & Rulings",d:4,q:"What role did Joyce Milgaard's 'epic struggle' play, and what does it reveal about the system?",a:"Her two decades of advocacy kept the case alive, revealing that correction depended on family persistence rather than the system itself",x:["She served as his lawyer in court","She proved the system corrects itself automatically","She convicted Larry Fisher"]},

/* ---------- Lesson 6: International Criminal Law ---------- */
{u:4,l:6,t:"Vocabulary",d:1,q:"What does nullum crimen sine lege mean?",a:"'No crime without a law' — a person cannot be punished for an act that was not criminal when committed",x:["'Extreme injustice is no law'","'The guilty act'","'A court of last resort'"]},
{u:4,l:6,t:"Vocabulary",d:1,q:"What is complementarity?",a:"The principle that the ICC only acts when national courts are unwilling or unable to prosecute a crime themselves",x:["The principle that states must consent to ICJ jurisdiction","The principle that treaties require ratification","The principle that courts follow precedent"]},
{u:4,l:6,t:"Vocabulary",d:1,q:"What is ratification?",a:"A country's formal, legally binding confirmation that it will be bound by a treaty it has signed",x:["A country's withdrawal from a treaty","A court's ruling on a treaty","The signing ceremony of a treaty"]},
{u:4,l:6,t:"Vocabulary",d:1,q:"What is the crime of aggression?",a:"The planning or execution of an act of armed force by a state against another state's sovereignty",x:["Murder committed during wartime","Any violent assault","A dispute between two states over a border"]},
{u:4,l:6,t:"People & Institutions",d:1,q:"Which court settles legal disputes between states?",a:"The International Court of Justice (ICJ)",x:["The International Criminal Court (ICC)","The Supreme Court of Canada","The Nuremberg Tribunal"]},
{u:4,l:6,t:"People & Institutions",d:1,q:"Which court prosecutes individuals for genocide, crimes against humanity, war crimes, and aggression?",a:"The International Criminal Court (ICC)",x:["The International Court of Justice (ICJ)","The UN Security Council","The Court of Appeal for Ontario"]},
{u:4,l:6,t:"Laws & Documents",d:1,q:"Which treaty established the ICC?",a:"The Rome Statute",x:["The UN Charter","The Geneva Conventions","The UDHR"]},
{u:4,l:6,t:"People & Institutions",d:1,q:"Where are both the ICJ and ICC based?",a:"The Hague",x:["Geneva","New York","Rome"]},
{u:4,l:6,t:"People & Institutions",d:1,q:"Which Canadian diplomat chaired the key Rome conference committee and became the ICC's first president?",a:"Philippe Kirsch",x:["John Peters Humphrey","Roméo Dallaire","Lester Pearson"]},
{u:4,l:6,t:"Laws & Documents",d:1,q:"Which Canadian law, passed in 2000, implemented the Rome Statute domestically?",a:"The Crimes Against Humanity and War Crimes Act",x:["The David and Joyce Milgaard's Law","The Criminal Code","The Canadian Bill of Rights"]},
{u:4,l:6,t:"Laws & Documents",d:1,q:"When was the Rome Statute adopted, and when did it enter into force?",a:"Adopted July 17, 1998; in force July 1, 2002",x:["Adopted 1945; in force 1948","Adopted 2000; in force 2010","Adopted 1982; in force 1985"]},
{u:4,l:6,t:"Cases & Rulings",d:1,q:"How many Nuremberg defendants were sentenced to death?",a:"Twelve",x:["Two","Twenty-four","None"]},
{u:4,l:6,t:"Laws & Documents",d:1,q:"How many countries are ICC member states, according to the course?",a:"125",x:["60","193","14"]},
{u:4,l:6,t:"People & Institutions",d:1,q:"What was the name of the coalition of nearly 60 states that Canada led at the Rome conference?",a:"The Like-Minded Group",x:["The Security Council","The Non-Aligned Movement","The Commonwealth"]},
{u:4,l:6,t:"Cases & Rulings",d:2,q:"What principle did Nuremberg defence lawyers argue was violated?",a:"Nullum crimen sine lege — crimes against humanity did not clearly exist in international law before the trials",x:["Complementarity","Habeas corpus","Stare decisis"]},
{u:4,l:6,t:"Cases & Rulings",d:2,q:"How did the Nuremberg tribunal answer the 'no crime without a law' objection?",a:"With natural law thinking: some acts are so fundamentally wrong that no formal law was needed to make them criminal",x:["By citing the Rome Statute","By dismissing all charges","By applying German domestic law"]},
{u:4,l:6,t:"Cases & Rulings",d:2,q:"How did legal positivists view the Nuremberg approach?",a:"As retroactive punishment dressed up as justice",x:["As the only valid approach","As consistent with positivism","As too lenient"]},
{u:4,l:6,t:"People & Institutions",d:2,q:"Can the ICJ convict or sentence an individual person?",a:"No — it only rules on disputes between countries",x:["Yes — for genocide","Yes — but only with Security Council approval","Only for the crime of aggression"]},
{u:4,l:6,t:"People & Institutions",d:2,q:"When can the ICJ hear a case?",a:"Only if the states involved consent to its jurisdiction",x:["Whenever the UN Secretary-General requests","Whenever a citizen files a complaint","Only on referral from the ICC"]},
{u:4,l:6,t:"People & Institutions",d:2,q:"When does the ICC generally have jurisdiction?",a:"When the accused's country is a member state, or on a UN Security Council referral",x:["Over any person anywhere automatically","Only over citizens of The Hague","Only when the ICJ refers a case"]},
{u:4,l:6,t:"Laws & Documents",d:2,q:"What condition triggered the Rome Statute's entry into force?",a:"Ratification by 60 countries",x:["Signature by the United States","A UN General Assembly vote","Approval by the ICJ"]},
{u:4,l:6,t:"People & Institutions",d:2,q:"What did Canada's Like-Minded Group push for?",a:"A prosecutor independent of the UN Security Council",x:["A court controlled by the Security Council","The exclusion of the crime of aggression","A court based in Ottawa"]},
{u:4,l:6,t:"Laws & Documents",d:2,q:"What is notable about Canada's Crimes Against Humanity and War Crimes Act?",a:"Canada was the first country to fully implement the Rome Statute into domestic law",x:["It withdrew Canada from the ICC","It was struck down under the Charter","It created the ICJ"]},
{u:4,l:6,t:"People & Institutions",d:2,q:"What did the United States do regarding the Rome Statute?",a:"Signed it but never ratified, and in 2002 formally withdrew its signature",x:["Ratified it first","Never signed it","Became the ICC's host country"]},
{u:4,l:6,t:"People & Institutions",d:2,q:"What are three criticisms of the ICC?",a:"It has no police force, its prosecutions have focused disproportionately on African states, and major powers like the U.S., China, and Russia are not members",x:["It is too fast, too cheap, and too popular","It prosecutes states instead of individuals","It is based in New York and controlled by Canada"]},
{u:4,l:6,t:"Theories & Concepts",d:2,q:"Why does Canada's domestic war crimes law matter for complementarity?",a:"By criminalizing these offences domestically, Canada retains the first right to prosecute its own nationals rather than deferring to the ICC",x:["It makes Canada exempt from the ICC","It lets the ICC prosecute Canadians first","It abolishes Canadian jurisdiction"]},
{u:4,l:6,t:"Theories & Concepts",d:2,q:"What does it mean that the ICC is a 'court of last resort'?",a:"It can only act when a country is unwilling or unable to prosecute the crime itself",x:["It is the final court of appeal for every country","It hears only death penalty cases","It can only hear one case per year"]},
{u:4,l:6,t:"Cases & Rulings",d:2,q:"How does the speed of Nuremberg compare to later international courts?",a:"Nuremberg concluded within about a year — astonishingly fast by the standards of courts that followed",x:["Nuremberg took decades","All international courts are equally fast","Nuremberg never concluded"]},
{u:4,l:6,t:"People & Institutions",d:3,q:"Two countries disagree over a maritime border. Which court could hear the dispute?",a:"The ICJ, if both states consent",x:["The ICC","The Supreme Court of Canada","The Nuremberg Tribunal"]},
{u:4,l:6,t:"Laws & Documents",d:3,q:"A general is accused of genocide, and his country refuses to prosecute him. Which court could act, and under what principle?",a:"The ICC, under complementarity",x:["The ICJ, under state consent","The ICC, under nullum crimen sine lege","The ICJ, under ratification"]},
{u:4,l:6,t:"Laws & Documents",d:3,q:"A Canadian citizen is accused of war crimes abroad. Who has the first right to prosecute?",a:"Canada, under its Crimes Against Humanity and War Crimes Act",x:["The ICC automatically","The ICJ","The UN Security Council"]},
{u:4,l:6,t:"Laws & Documents",d:3,q:"A country signs a treaty but its legislature never formally confirms it. Is the country bound?",a:"Not fully — ratification is the formal, legally binding confirmation",x:["Yes — signature alone is binding","Yes — the ICC enforces it","No country is ever bound by treaties"]},
{u:4,l:6,t:"Laws & Documents",d:3,q:"A defendant argues he cannot be punished because the act wasn't illegal when he did it. Which principle is he invoking?",a:"Nullum crimen sine lege",x:["Complementarity","Mens rea","Stare decisis"]},
{u:4,l:6,t:"People & Institutions",d:3,q:"A state invades another state's territory. Which ICC crime is this?",a:"The crime of aggression",x:["Genocide","Crimes against humanity","War crimes"]},
{u:4,l:6,t:"People & Institutions",d:3,q:"The ICC issues an arrest warrant but the suspect's country refuses to hand him over. What limitation does this show?",a:"The ICC has no police force and relies entirely on member states for enforcement",x:["The ICC can send its own army","The ICJ will arrest him","The warrant is automatically enforced by the UN"]},
{u:4,l:6,t:"Laws & Documents",d:3,q:"A country joins the ICC but has strong domestic courts and never needs the ICC to prosecute its citizens. Why is this consistent with the Rome Statute?",a:"Complementarity means a functioning domestic system prosecutes first; the ICC steps in only if it is unwilling or unable",x:["It shows the country has withdrawn","It violates the Rome Statute","It means the ICC has no jurisdiction anywhere"]},
{u:4,l:6,t:"Cases & Rulings",d:4,q:"How does the Nuremberg 'no crime without a law' debate connect to Unit 1's schools of legal thought?",a:"Natural law says some acts are self-evidently criminal; positivism says punishment requires a pre-existing enacted law",x:["Both schools agreed with the defence","Critical legal theory decided the case","Legal realism created the Rome Statute"]},
{u:4,l:6,t:"Laws & Documents",d:4,q:"Why did the Nuremberg tension 'never fully go away'?",a:"It resurfaces whenever the international community defines new categories of atrocity crime, including when drafting the Rome Statute",x:["Because Nuremberg was never concluded","Because the ICJ overturned Nuremberg","Because positivism was abolished"]},
{u:4,l:6,t:"Laws & Documents",d:4,q:"Is a court that depends entirely on member states for enforcement really a 'court of last resort'? What is the strongest critique?",a:"Without its own enforcement and with major powers outside it, it may be unable to act precisely when a state refuses to cooperate",x:["It is stronger than any domestic court","Enforcement is irrelevant to a court's authority","The ICC has never faced this problem"]},
{u:4,l:6,t:"People & Institutions",d:4,q:"Compare the ICJ and ICC in one sentence.",a:"The ICJ settles disputes between consenting states; the ICC prosecutes individuals for the gravest international crimes as a court of last resort",x:["Both prosecute individuals","Both settle disputes between states","The ICJ is a criminal court and the ICC a civil court"]},
{u:4,l:6,t:"People & Institutions",d:4,q:"Why is Canada's leadership in creating the ICC significant for a CLN4U student?",a:"It shows Canada actively shaping international criminal law, through Kirsch's role, the Like-Minded Group, and first domestic implementation",x:["It shows Canada opposed the ICC","It shows Canada controls the ICC","It shows Canada withdrew its signature"]},
{u:4,l:6,t:"People & Institutions",d:4,q:"How does the accusation of 'selective justice' against the ICC connect to Unit 1's Critical Legal Theory?",a:"A critic could argue the court reflects global power imbalances, prosecuting weaker states while major powers remain outside",x:["It proves the ICC follows natural law","It shows the ICC is a legal realist institution","It is unrelated to any legal theory"]},

/* ---------- Lesson 7: Synthesis ---------- */
{u:4,l:7,t:"Theories & Concepts",d:1,q:"What corrected the wrongful convictions in every case studied in this unit?",a:"New forensic science (DNA testing) unavailable at the original trial",x:["A confession from police","A Supreme Court order","A change in government"]},
{u:4,l:7,t:"Theories & Concepts",d:1,q:"Which case alone produced a permanent, structural change to the justice system?",a:"David Milgaard's",x:["The Central Park Five","The West Memphis Three","Nuremberg"]},
{u:4,l:7,t:"Theories & Concepts",d:1,q:"What is the unit's lens or mantra?",a:"'The System Is Only as Just as Its Weakest Case.'",x:["'Understand the System — Then Question It.'","'Rights Are Not Given — They Are Recognized.'","'One Law for All.'"]},
{u:4,l:7,t:"Theories & Concepts",d:1,q:"How many of the four people in this unit's case studies were exonerated by DNA evidence?",a:"Three",x:["One","Two","All four"]},
{u:4,l:7,t:"Theories & Concepts",d:2,q:"What went wrong in the Central Park Five case, in summary?",a:"Coerced juvenile confessions, media-driven tunnel vision, and a rush to reassure a frightened public",x:["A moral panic and a coerced confession from a suspect with an intellectual disability","Pressured witnesses and a missed police tip","A retroactive law and a fast trial"]},
{u:4,l:7,t:"Theories & Concepts",d:2,q:"What went wrong in the West Memphis Three case, in summary?",a:"A moral panic, a coerced confession from a suspect with an intellectual disability, and forensic conclusions called outlandish by experts",x:["Coerced juvenile confessions and media tunnel vision","Pressured witness statements and a missed tip","A paid informant and undisclosed convictions"]},
{u:4,l:7,t:"Theories & Concepts",d:2,q:"What went wrong in the Milgaard case, in summary?",a:"Pressured witness statements, a credible alternative suspect never pursued, and a missed police tip left unexamined for a decade",x:["A satanic panic and a knife","Juvenile confessions and a wolf-pack narrative","A retroactive prosecution"]},
{u:4,l:7,t:"Theories & Concepts",d:2,q:"Besides DNA, what corrected each case?",a:"Sustained external pressure — documentaries, advocates, investigators, or family members who refused to let the case close",x:["Automatic annual review by courts","A confession from the police","A new statute in each country"]},
{u:4,l:7,t:"Theories & Concepts",d:2,q:"Why do Charter legal rights (s.7–14) matter for this unit?",a:"They exist specifically to prevent the process failures studied: the right to counsel, to remain silent, and to a fair trial",x:["They apply only to international crimes","They are abstract and rarely used","They protect only victims"]},
{u:4,l:7,t:"Theories & Concepts",d:2,q:"What new questions does DNA technology raise, beyond freeing the innocent?",a:"Privacy questions about DNA databases, surveillance, and predictive policing",x:["Whether DNA is admissible","Whether juries can understand science","Whether DNA replaces judges"]},
{u:4,l:7,t:"Theories & Concepts",d:2,q:"What shared demand do the smallest and largest scales of criminal law make?",a:"That guilt be established through fair process, not public pressure, political convenience, or a rush to closure",x:["That every case go to the ICC","That confessions be required","That trials be as fast as Nuremberg"]},
{u:4,l:7,t:"Theories & Concepts",d:2,q:"Why does complementarity make domestic justice the 'foundation' of the international system?",a:"The ICC assumes domestic courts are the first and most important line of defence, so domestic fairness underpins everything",x:["Because the ICC prosecutes every case","Because domestic courts are irrelevant","Because the ICJ reviews all domestic verdicts"]},
{u:4,l:7,t:"Theories & Concepts",d:2,q:"From what scale to what scale did this unit move?",a:"From one accused person in one trial to an international court built to hold governments and leaders accountable",x:["From international law to provincial offences","From civil law to tort law","From Ontario courts to the Senate"]},
{u:4,l:7,t:"Cases & Rulings",d:3,q:"A conviction rests on a confession from a frightened teenager, media pressure, and no physical evidence. Which case pattern does it match most closely?",a:"The Central Park Five",x:["Nuremberg","The Rwandan genocide","Delgamuukw"]},
{u:4,l:7,t:"Cases & Rulings",d:3,q:"New DNA technology becomes available decades after a conviction. Whose responsibility is it to revisit the case? Which options does the course raise?",a:"The defendant, the courts, or the government — the course asks students to argue which",x:["Only the original jury","Only the ICC","No one — convictions are final"]},
{u:4,l:7,t:"Modern Connections",d:3,q:"A police department proposes predictive policing using a DNA database. Which Lesson 7 concern does this raise?",a:"Privacy — the same forensic technology that frees the innocent can expand surveillance",x:["Complementarity","Nullum crimen sine lege","Strict liability"]},
{u:4,l:7,t:"People & Institutions",d:3,q:"A country's own courts are unable to prosecute a war crime. According to the unit's synthesis, what does this reveal?",a:"That a failure at the domestic level is what triggers the ICC — the foundation has given way",x:["That the ICJ must intervene","That the crime is not serious","That the country must leave the ICC"]},
{u:4,l:7,t:"Cases & Rulings",d:3,q:"A prosecutor pushes for a quick conviction to calm a frightened community. Which 'demand' from the synthesis is violated?",a:"That guilt be established through fair process, not a rush to closure",x:["That trials be fast","That confessions be obtained","That the ICC be consulted"]},
{u:4,l:7,t:"Cases & Rulings",d:3,q:"A student says they now trust confessions less after this unit. Which Lesson 2 evidence point supports this?",a:"False confessions are well-documented, especially from young or vulnerable suspects under coercive interrogation",x:["Confessions are always accurate","Confessions are inadmissible in Canada","Only DNA is ever used at trial"]},
{u:4,l:7,t:"Modern Connections",d:4,q:"As forensic and surveillance technology improves, will wrongful convictions become rarer, or will new errors replace them? What does the unit suggest?",a:"Better science can prevent some errors, but new technologies bring new risks — the system's fairness still depends on process, not just tools",x:["Technology will eliminate all errors","Technology has no effect on convictions","Only DNA errors will remain"]},
{u:4,l:7,t:"People & Institutions",d:4,q:"Why does the unit say domestic justice is 'in a real sense' the foundation of the international system?",a:"Under complementarity, the ICC acts only when domestic courts fail, so fair domestic process is what the whole structure depends on",x:["Because the ICC is a domestic court","Because international law has no courts","Because domestic courts enforce ICC rulings"]},
{u:4,l:7,t:"Cases & Rulings",d:4,q:"How does the unit's mantra apply to both a wrongful conviction and the ICC?",a:"One unjust case — a coerced confession or an unprosecuted atrocity — reveals the limit of the whole system's justice",x:["It applies only to Canadian cases","It applies only to international courts","It means weak cases should be dismissed"]},
{u:4,l:7,t:"Theories & Concepts",d:4,q:"What single pattern recurs across all four cases in this unit?",a:"Guilt established under pressure — public fear, political convenience, or a rush to closure — rather than through fair process",x:["All four involved DNA from the start","All four were Canadian","All four involved the ICC"]},
{u:4,l:7,t:"Theories & Concepts",d:4,q:"Why does the course connect Unit 3's 'corresponding responsibilities' to Unit 4?",a:"Legal rights only protect the accused if citizens and institutions take seriously the responsibility to respect them, even for those accused of terrible crimes",x:["Because responsibilities replace rights in criminal law","Because the accused has no rights","Because responsibilities apply only to victims"]},
{u:4,l:7,t:"Cases & Rulings",d:4,q:"Compare what 'corrected' the wrongful convictions with what 'caused' them. What does the comparison reveal?",a:"The causes were internal to the system (tunnel vision, coercion), while correction came mostly from outside it (DNA, advocates, families)",x:["The system corrected itself automatically in every case","Causes and corrections were both external","Nothing corrected the cases"]}
);
